settings.custom_liquid:
{%- comment -%}
  Paste this ENTIRE file into a "Custom Liquid" block's Liquid text field
  (Theme Customizer -> product page -> Add block -> Custom Liquid).
  Do NOT include any {% schema %} tag here — that only belongs in a real
  theme block file, not inside this settings field.
{%- endcomment -%}

{%- assign variant = product.selected_or_first_available_variant -%}
{%- assign bridge_server_url = 'https://stripe-shopify-bridge.onrender.com' -%}
{%- assign stripe_publishable_key = 'pk_test_51TzHJoQS74MQmWo47ZMd3wKjNwOfSnh8X97gxi3RJxREHdal0rnl9WVdWO8czW32q7hLqSSCYQAEMFwfeBlR5a0Y00nanWAbj6' -%}

<button type="button" id="stripe-buy-button" class="button button--full-width" style="width: 100%; min-height: 48px; display: flex; align-items: center; justify-content: center; font-weight: 400; font-size: clamp(16px, 2vw, 20px); letter-spacing: -0.5px; white-space: nowrap; padding: 12px 16px; margin-top: -10px;">
  Buy Now
</button>

<div id="stripe-checkout-modal" style="display:none; position:fixed; inset:0; z-index:9999; background:rgba(0,0,0,0.5); align-items:center; justify-content:center;">
  <div style="background:#fff; border-radius:8px; max-width:480px; width:92%; max-height:88vh; overflow:auto; position:relative; padding:8px;">
    <button type="button" id="stripe-checkout-close" aria-label="Close" style="position:absolute; top:8px; right:8px; background:none; border:none; font-size:22px; line-height:1; cursor:pointer; z-index:1;">&times;</button>
    <div id="stripe-checkout-container" style="min-height:400px;"></div>
  </div>
</div>

<script src="https://js.stripe.com/v3/"></script>
<script>
  (function () {
    var BRIDGE_URL = {{ bridge_server_url | json }};
    var PUBLISHABLE_KEY = {{ stripe_publishable_key | json }};
    var variant = {{ variant | json }};
    var productTitle = {{ product.title | json }};
    var shopCurrency = {{ shop.currency | json }};

    var stripe = Stripe(PUBLISHABLE_KEY);
    var checkout = null;

    var button = document.getElementById('stripe-buy-button');
    var modal = document.getElementById('stripe-checkout-modal');
    var closeBtn = document.getElementById('stripe-checkout-close');
    var container = document.getElementById('stripe-checkout-container');

    function openModal() {
      modal.style.display = 'flex';
    }

    function closeModal() {
      modal.style.display = 'none';
      if (checkout) {
        checkout.destroy();
        checkout = null;
      }
      container.innerHTML = '';
    }

    async function fetchClientSecret() {
      var res = await fetch(BRIDGE_URL + '/create-embedded-checkout-session', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          items: [
            {
              variantId: 'gid://shopify/ProductVariant/' + variant.id,
              name: productTitle,
              price: variant.price / 100,
              quantity: 1,
            },
          ],
          currency: shopCurrency.toLowerCase(),
          returnUrl: window.location.href.split('?')[0],
        }),
      });
      var data = await res.json();
      if (!res.ok) throw new Error(data.error || 'Could not start checkout');
      return data.clientSecret;
    }

    button.addEventListener('click', async function () {
      button.disabled = true;
      openModal();
      container.innerHTML = '<p style="padding:24px; text-align:center;">Loading payment form&hellip;</p>';
      try {
        checkout = await stripe.initEmbeddedCheckout({ fetchClientSecret: fetchClientSecret });
        container.innerHTML = '';
        checkout.mount('#stripe-checkout-container');
      } catch (err) {
        container.innerHTML = '<p style="padding:24px; color:#c00;">' + err.message + '</p>';
      } finally {
        button.disabled = false;
      }
    });

    closeBtn.addEventListener('click', closeModal);
    modal.addEventListener('click', function (e) {
      if (e.target === modal) closeModal();
    });

    (function checkReturn() {
      var params = new URLSearchParams(window.location.search);
      var sessionId = params.get('session_id');
      if (!sessionId) return;
      fetch(BRIDGE_URL + '/session-status?session_id=' + encodeURIComponent(sessionId))
        .then(function (r) { return r.json(); })
        .then(function (data) {
          if (data.paymentStatus === 'paid') {
            openModal();
            container.innerHTML = '<div style="padding:32px; text-align:center;"><h3>Payment successful</h3><p>Thanks' + (data.customerEmail ? ', a confirmation was sent to ' + data.customerEmail : '') + '. Your order is being created.</p></div>';
          }
        });
    })();
  })();
</script>
